//! Shared setup of the terrain / pipeline golden tests (fixture `tests/fixtures/terrain_golden.txt`,
//! generated by `tests/oracle/TerrainOracle.java`).
#![allow(dead_code, reason = "each test binary uses a subset of the shared helpers")]

use std::collections::BTreeMap;
use std::path::PathBuf;
use std::sync::{Arc, LazyLock};

use mc_core::ident::Identifier;
use mc_core::pos::block_pos::BlockPos;
use mc_core::pos::chunk_pos::ChunkPos;
use mc_world::chunk::{LevelHeight, ProtoChunk};
use mc_world::heightmap::HeightmapType;
use mc_world::palette::{BiomeId, PalettedContainerFactory};
use mc_world::status::ChunkStatus;
use mc_world::upgrade_data::UpgradeData;
use mc_worldgen::biome::{BiomeRegistry, BiomeSource, biome_source_from_json};
use mc_worldgen::data::{FsDataSource, WorldgenRegistries};
use mc_worldgen::generator::NoiseBasedChunkGenerator;
use mc_worldgen::random_state::RandomState;

pub const SETTINGS: [&str; 7] = ["overworld", "large_biomes", "amplified", "nether", "end", "caves", "floating_islands"];
pub const SEEDS: [i64; 3] = [0, 12345, -4172144997902289642];

pub struct World {
    pub registries: Arc<WorldgenRegistries>,
    pub biomes: Arc<BiomeRegistry>,
    pub factory: PalettedContainerFactory,
}

pub static WORLD: LazyLock<World> = LazyLock::new(|| {
    let root = PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("../../ref/src/data");
    let registries = Arc::new(WorldgenRegistries::new(Arc::new(FsDataSource::new(root))));
    let biomes = Arc::new(BiomeRegistry::load(&registries).expect("biome registry"));
    let factory = PalettedContainerFactory::create(mc_world::palette::BiomeRegistry::new(biomes.names())).expect("plains");
    World { registries, biomes, factory }
});

/// The dimension height the oracle uses for a noise settings name.
pub fn level_height(setting: &str) -> LevelHeight {
    match setting {
        "overworld" | "large_biomes" | "amplified" | "caves" => LevelHeight::new(-64, 384),
        _ => LevelHeight::new(0, 256),
    }
}

pub fn biome_source(setting: &str) -> Arc<dyn BiomeSource> {
    let json = match setting {
        "nether" => serde_json::json!({"type": "minecraft:multi_noise", "preset": "minecraft:nether"}),
        "end" | "floating_islands" => serde_json::json!({"type": "minecraft:the_end"}),
        _ => serde_json::json!({"type": "minecraft:multi_noise", "preset": "minecraft:overworld"}),
    };
    biome_source_from_json(&json, &WORLD.registries, &WORLD.biomes).expect("biome source")
}

pub fn generator(setting: &str) -> NoiseBasedChunkGenerator {
    let settings = WORLD
        .registries
        .noise_settings(&Identifier::with_default_namespace(setting).unwrap())
        .unwrap_or_else(|e| panic!("{setting}: {e}"));
    NoiseBasedChunkGenerator::new(biome_source(setting), Arc::new(settings), WORLD.registries.clone(), WORLD.biomes.clone())
        .unwrap_or_else(|e| panic!("{setting}: {e}"))
}

pub fn random_state(generator: &NoiseBasedChunkGenerator, seed: i64) -> Arc<RandomState> {
    Arc::new(RandomState::create(WORLD.registries.clone(), seed, generator.settings()))
}

pub fn new_chunk(setting: &str, x: i32, z: i32) -> ProtoChunk {
    ProtoChunk::new(ChunkPos::new(x, z), UpgradeData::EMPTY, level_height(setting), &WORLD.factory, None)
}

/// A chunk whose biomes exist and whose persisted status is `BIOMES` (what `buildTerrain` sees in the pipeline).
pub fn biome_chunk(
    generator: &NoiseBasedChunkGenerator,
    setting: &str,
    random_state: &Arc<RandomState>,
    x: i32,
    z: i32,
) -> ProtoChunk {
    use mc_worldgen::generator::ChunkGenerator;
    let mut chunk = new_chunk(setting, x, z);
    generator.create_biomes(random_state, &mc_worldgen::blending::Blender::empty(), &mut chunk);
    chunk.set_persisted_status(ChunkStatus::Biomes);
    chunk
}

pub fn fnv_word(mut h: u64, word: u32) -> u64 {
    for i in 0..4 {
        h ^= u64::from((word >> (8 * i)) & 0xFF);
        h = h.wrapping_mul(0x100000001b3);
    }
    h
}

pub fn fnv_long(h: u64, word: i64) -> u64 {
    fnv_word(fnv_word(h, word as u32), (word >> 32) as u32)
}

pub const FNV_INIT: u64 = 0xcbf29ce484222325;

pub fn section_hashes(chunk: &ProtoChunk) -> String {
    let min_y = chunk.access.min_y();
    let pos = chunk.pos();
    let mut out = String::new();
    for s in 0..chunk.access.level_height.sections_count() as i32 {
        let mut h = FNV_INIT;
        let base_y = min_y + s * 16;
        for y in 0..16 {
            for z in 0..16 {
                for x in 0..16 {
                    let state = chunk.get_block_state(BlockPos::new(pos.get_min_block_x() + x, base_y + y, pos.get_min_block_z() + z));
                    h = fnv_word(h, state.id());
                }
            }
        }
        out.push_str(&format!(" {h:016x}"));
    }
    out
}

pub fn biome_hash(chunk: &ProtoChunk) -> u64 {
    let mut h = FNV_INIT;
    let q_min_y = chunk.access.min_y() >> 2;
    let q_max_y = q_min_y + (chunk.access.height() >> 2);
    let pos = chunk.pos();
    for qy in q_min_y..q_max_y {
        for qz in 0..4 {
            for qx in 0..4 {
                let b = chunk.access.get_noise_biome(pos.get_min_block_x() / 4 + qx, qy, pos.get_min_block_z() / 4 + qz);
                let name = WORLD.biomes.key(b).to_string();
                for byte in name.bytes().chain(std::iter::once(b'\n')) {
                    h ^= u64::from(byte);
                    h = h.wrapping_mul(0x100000001b3);
                }
            }
        }
    }
    h
}

pub fn heightmap_name(ty: HeightmapType) -> &'static str {
    match ty {
        HeightmapType::WorldSurfaceWg => "WORLD_SURFACE_WG",
        HeightmapType::WorldSurface => "WORLD_SURFACE",
        HeightmapType::OceanFloorWg => "OCEAN_FLOOR_WG",
        HeightmapType::OceanFloor => "OCEAN_FLOOR",
        HeightmapType::MotionBlocking => "MOTION_BLOCKING",
        HeightmapType::MotionBlockingNoLeaves => "MOTION_BLOCKING_NO_LEAVES",
    }
}

/// `"<type> <hash>"` per primed heightmap, in `Heightmap.Types` order.
pub fn heightmap_lines(chunk: &mut ProtoChunk) -> Vec<String> {
    let mut lines = Vec::new();
    for ty in HeightmapType::ALL {
        if chunk.access.has_primed_heightmap(ty) {
            let mut h = FNV_INIT;
            for &l in chunk.access.get_or_create_heightmap_unprimed(ty).get_raw_data() {
                h = fnv_long(h, l);
            }
            lines.push(format!("{} {h:016x}", heightmap_name(ty)));
        }
    }
    lines
}

pub fn post_processing_hash(chunk: &ProtoChunk) -> u64 {
    let mut h = FNV_INIT;
    for (i, list) in chunk.access.post_processing.iter().enumerate() {
        h = fnv_word(h, (-1 - i as i32) as u32);
        for &s in list.iter().flatten() {
            h = fnv_word(h, i32::from(s) as u32);
        }
    }
    h
}

/// Fixture lines grouped by tag: `tag -> [(key fields joined by ' ', rest)]`, keyed by the first `key_len` fields.
pub fn fixture(tag: &str, key_len: usize) -> BTreeMap<String, Vec<String>> {
    let text = std::fs::read_to_string(PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("tests/fixtures/terrain_golden.txt"))
        .expect("fixture present");
    let mut out: BTreeMap<String, Vec<String>> = BTreeMap::new();
    for line in text.lines() {
        let mut parts = line.splitn(2 + key_len, ' ');
        if parts.next() != Some(tag) {
            continue;
        }
        let key: Vec<&str> = (&mut parts).take(key_len).collect();
        out.entry(key.join(" ")).or_default().push(parts.next().unwrap_or("").to_owned());
    }
    out
}

pub fn parse_key(key: &str) -> (String, i64, i32, i32) {
    let p: Vec<&str> = key.split(' ').collect();
    (p[0].to_owned(), p[1].parse().unwrap(), p[2].parse().unwrap(), p[3].parse().unwrap())
}

pub fn report(what: &str, checked: usize, mismatches: &[String]) {
    assert!(mismatches.is_empty(), "{what}: {} of {checked} mismatches, first: {:#?}", mismatches.len(), &mismatches[..mismatches.len().min(8)]);
    assert!(checked > 0, "{what}: nothing checked");
}

pub fn biome_id(name: &str) -> BiomeId {
    WORLD.biomes.id_of_name(name).expect("biome")
}
